<script setup lang="ts">import {Plus,Trash2,ArrowDown} from 'lucide-vue-next';import ZButton from '@/components/zs/ZButton.vue';import type {SequenceStep} from '@/types/crm';const p=defineProps<{modelValue:SequenceStep[]}>();const emit=defineEmits<{ 'update:modelValue':[steps:SequenceStep[]];regenerate:[index:number]}>();function patch(i:number,key:keyof SequenceStep,value:string|number){emit('update:modelValue',p.modelValue.map((s,n)=>n===i?{...s,[key]:value}:s))}function add(){emit('update:modelValue',[...p.modelValue,{id:crypto.randomUUID(),subject:'',body:'',delayDays:3}])}function remove(i:number){emit('update:modelValue',p.modelValue.filter((_,n)=>n!==i))};</script>
<template><div class="space-y-3"><template v-for="(step,i) in modelValue" :key="step.id"><article class="panel p-4"><div class="flex items-center justify-between"><p class="text-sm font-semibold text-content">Email {{i+1}}</p><div class="flex gap-1"><ZButton variant="ghost" @click="$emit('regenerate',i)">Regenerate</ZButton><ZButton variant="ghost" aria-label="Delete step" @click="remove(i)"><Trash2 class="size-3.5"/></ZButton></div></div><label class="mt-3 block"><span class="label-caps">Subject</span><input class="field mt-1.5" :value="step.subject" @input="patch(i,'subject',($event.target as HTMLInputElement).value)"/></label><label class="mt-3 block"><span class="label-caps">Email body</span><textarea class="field mt-1.5 min-h-36" :value="step.body" @input="patch(i,'body',($event.target as HTMLTextAreaElement).value)"></textarea></label></article><div v-if="i<modelValue.length-1" class="flex items-center justify-center gap-2 text-xs text-content-muted"><ArrowDown class="size-3.5"/>Wait <input class="field h-7 w-14 px-2 text-center" type="number" min="1" :value="modelValue[i+1]?.delayDays" @input="patch(i+1,'delayDays',Number(($event.target as HTMLInputElement).value))"/> days</div></template><ZButton variant="outline" @click="add"><Plus class="size-3.5"/>Add email</ZButton></div></template>
